// Test Cases E2E para GymRatFlow
// Filtra los tests activos (no DEPRECATED/SKIP)

const testCases = [
  {
    id: "TC001",
    name: "Bloqueo de Ruido - Status Update",
    priority: "CRITICAL",
    category: "FILTRO_RUIDO",
    metrics: {
