      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "statuses": [{ "id": "wamid.test", "status": "sent", "timestamp": "1769084739", "recipient_id": "573208780020" }],
      "field": "messages"
    }]
  },
  {
    id: "TC002",
    name: "Usuario Nuevo - Onboarding KYC",
    priority: "HIGH",
    category: "ONBOARDING",
    metrics: {
      rule: "output.includes('conocerte') || output.includes('nombre') || output.includes('Coach')",
      description: "Debe iniciar KYC"
    },
    input: [{
      "messaging_product": "whatsapp",
      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "contacts": [{ "profile": { "name": "Test NewUser" }, "wa_id": "570000000009" }],
      "messages": [{ "from": "570000000009", "id": "wamid.E2E-TC002", "timestamp": "1769085000", "text": { "body": "Hola, quiero empezar a entrenar" }, "type": "text" }],
      "field": "messages"
    }]
  },
  {
    id: "TC003",
    name: "Usuario sin Workouts - Flujo Agendar",
    priority: "HIGH",
    category: "AGENDAR",
    metrics: {
      rule: "output.includes('dias') || output.includes('días') || output.includes('semana')",
      description: "Debe ofrecer agendar semana"
    },
    input: [{
      "messaging_product": "whatsapp",
      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "contacts": [{ "profile": { "name": "Test NoSchedule" }, "wa_id": "570000000001" }],
      "messages": [{ "from": "570000000001", "id": "wamid.E2E-TC003", "timestamp": "1769085000", "text": { "body": "Quiero agendar mi semana" }, "type": "text" }],
      "field": "messages"
    }]
  },
  {
    id: "TC004",
    name: "Dia de Descanso",
    priority: "MEDIUM",
    category: "DESCANSO",
    metrics: {
      rule: "output.includes('no tienes sesión') || output.includes('no tienes sesion') || output.includes('descansar') || output.includes('descanso')",
      description: "Debe indicar día de descanso"
    },
    input: [{
      "messaging_product": "whatsapp",
      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "contacts": [{ "profile": { "name": "Test RestDay" }, "wa_id": "570000000002" }],
      "messages": [{ "from": "570000000002", "id": "wamid.E2E-TC004", "timestamp": "1769085000", "text": { "body": "Que hay para hoy?" }, "type": "text" }],
      "field": "messages"
    }]
  },
  {
    id: "TC006",
    name: "VER_RUTINA_DE_HOY",
    priority: "HIGH",
    category: "VER_RUTINA",
    metrics: {
      rule: "(output.includes('RUTINA') || output.includes('rutina')) && (output.includes('Series') || output.includes('series') || output.includes('ejercicio'))",
      description: "Debe mostrar rutina formateada"
    },
    input: [{
      "messaging_product": "whatsapp",
      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "contacts": [{ "profile": { "name": "Test WithRoutine" }, "wa_id": "570000000003" }],
      "messages": [{ "from": "570000000003", "id": "wamid.E2E-TC006", "timestamp": "1769085000", "text": { "body": "Muestrame mi rutina de hoy" }, "type": "text" }],
      "field": "messages"
    }]
  },
  {
    id: "TC007",
    name: "CHAT - Pregunta General",
    priority: "MEDIUM",
    category: "CHAT",
    metrics: {
      rule: "output !== undefined && output.length > 50",
      description: "Debe responder pregunta fitness"
    },
    input: [{
      "messaging_product": "whatsapp",
      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "contacts": [{ "profile": { "name": "Test WithRoutine" }, "wa_id": "570000000003" }],
      "messages": [{ "from": "570000000003", "id": "wamid.E2E-TC007", "timestamp": "1769085000", "text": { "body": "Que ejercicio es mejor para biceps?" }, "type": "text" }],
      "field": "messages"
    }]
  },
  {
    id: "TC011",
    name: "Confirmacion via Pending Task",
    priority: "CRITICAL",
    category: "PENDING_TASK",
    metrics: {
      rule: "output.includes('felicit') || output.includes('excelente') || output.includes('increíble') || output.includes('genial') || output.includes('Completada')",
      description: "Debe confirmar rutina completada"
    },
    cleanup: [
      "UPDATE user_weekly_schedule SET \"Completed\" = false WHERE user_id = 'e2e00004-0000-0000-0000-000000000004' AND planned_day = CURRENT_DATE;",
      "UPDATE pending_tasks SET status = 'pending', resolved_at = NULL WHERE user_id = 'e2e00004-0000-0000-0000-000000000004' AND task_type = 'CONFIRMAR_RUTINA';"
    ],
    input: [{
      "messaging_product": "whatsapp",
      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "contacts": [{ "profile": { "name": "Test WithPendingTask" }, "wa_id": "570000000004" }],
      "messages": [{ "from": "570000000004", "id": "wamid.E2E-TC011", "timestamp": "1769085000", "text": { "body": "Si, ya terminé mi rutina" }, "type": "text" }],
      "field": "messages"
    }]
  },
  {
    id: "TC012",
    name: "Pending Task - No confirma",
    priority: "HIGH",
    category: "PENDING_TASK",
    metrics: {
      rule: "output !== undefined && output.length > 30",
      description: "Debe manejar no-confirmación"
    },
    cleanup: [
      "UPDATE pending_tasks SET status = 'pending', resolved_at = NULL WHERE user_id = 'e2e00004-0000-0000-0000-000000000004' AND task_type = 'CONFIRMAR_RUTINA';"
    ],
    input: [{
      "messaging_product": "whatsapp",
      "metadata": { "display_phone_number": "573213413664", "phone_number_id": "914510145083991" },
      "contacts": [{ "profile": { "name": "Test WithPendingTask" }, "wa_id": "570000000004" }],
      "messages": [{ "from": "570000000004", "id": "wamid.E2E-TC012", "timestamp": "1769085000", "text": { "body": "No pude hoy, me senti mal" }, "type": "text" }],
      "field": "messages"
    }]
  }
];

// Inicializar estado global del test run
$execution.customData.set('startTime', new Date().toISOString());
$execution.customData.set('totalTests', testCases.length);
$execution.customData.set('testResults', '[]');

return testCases.map(tc => ({ json: tc }));

// Pre-process: preparar el test case actual
const testCase = $input.first().json;

console.log(`\n========================================`);
console.log(`🧪 Ejecutando: ${testCase.id} - ${testCase.name}`);
console.log(`   Categoria: ${testCase.category}`);
console.log(`   Prioridad: ${testCase.priority}`);
console.log(`========================================`);

return [{ json: testCase }];

// Extraer solo el input del test case para pasarlo al sub-workflow
const testCase = $('Pre-Test Log').first().json;
const whatsappInput = testCase.input[0];

// Retornar el objeto WhatsApp directamente
return [{ json: whatsappInput }];

// Evaluar resultado del test
const testCase = $('Pre-Test Log').first().json;
const workflowResult = $input.first().json;

// Extraer el output del workflow
let output = '';
try {
  if (workflowResult.output) {
    output = workflowResult.output;
  } else if (workflowResult.text) {
    output = workflowResult.text;
  } else if (typeof workflowResult === 'string') {
    output = workflowResult;
  } else {
    const findOutput = (obj) => {
      if (!obj || typeof obj !== 'object') return '';
      if (obj.output) return obj.output;
      if (obj.text) return obj.text;
      for (const key of Object.keys(obj)) {
        const found = findOutput(obj[key]);
        if (found) return found;
      }
      return '';
    };
    output = findOutput(workflowResult);
  }
} catch (e) {
  output = '';
}

// Evaluar la métrica
let passed = false;
let error = null;

try {
  const rule = testCase.metrics.rule;
  passed = eval(rule);
} catch (e) {
  error = e.message;
  passed = false;
}

const result = {
  testId: testCase.id,
  testName: testCase.name,
  category: testCase.category,
  priority: testCase.priority,
  passed: passed,
  output: output ? output.substring(0, 500) : '(empty)',
  expectedRule: testCase.metrics.rule,
  ruleDescription: testCase.metrics.description,
  error: error,
  executedAt: new Date().toISOString()
};

// Guardar resultado en customData para agregarlo al final
let allResults = [];
try {
  const existing = $execution.customData.get('testResults');
  if (existing) allResults = JSON.parse(existing);
} catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));

console.log(`${passed ? '✅ PASSED' : '❌ FAILED'}: ${testCase.id} - ${testCase.name}`);

return [{ json: result }];

// Generar reporte final - leer de customData
let results = [];
try {
  const stored = $execution.customData.get('testResults');
  if (stored) results = JSON.parse(stored);
} catch(e) {
  results = [];
}

const passed = results.filter(r => r.passed);
const failed = results.filter(r => !r.passed);

const report = {
  summary: {
    totalTests: results.length,
    passed: passed.length,
    failed: failed.length,
    passRate: results.length > 0 ? ((passed.length / results.length) * 100).toFixed(1) + '%' : '0%',
    executedAt: new Date().toISOString()
  },
  byPriority: {
    CRITICAL: {
      total: results.filter(r => r.priority === 'CRITICAL').length,
      passed: results.filter(r => r.priority === 'CRITICAL' && r.passed).length,
      failed: results.filter(r => r.priority === 'CRITICAL' && !r.passed).map(r => r.testId)
    },
    HIGH: {
      total: results.filter(r => r.priority === 'HIGH').length,
      passed: results.filter(r => r.priority === 'HIGH' && r.passed).length,
      failed: results.filter(r => r.priority === 'HIGH' && !r.passed).map(r => r.testId)
    },
    MEDIUM: {
      total: results.filter(r => r.priority === 'MEDIUM').length,
      passed: results.filter(r => r.priority === 'MEDIUM' && r.passed).length,
      failed: results.filter(r => r.priority === 'MEDIUM' && !r.passed).map(r => r.testId)
    }
  },
  failedTests: failed.map(r => ({
    id: r.testId,
    name: r.testName,
    category: r.category,
    priority: r.priority,
    expected: r.ruleDescription,
    actualOutput: (r.output || '(empty)').substring(0, 300)
  })),
  allResults: results
};

// Log del reporte
console.log('\n');
console.log('╔════════════════════════════════════════════════════════════╗');
console.log('║           📊 REPORTE E2E - GymRatFlow                      ║');
console.log('╠════════════════════════════════════════════════════════════╣');
console.log(`║  Total Tests:  ${report.summary.totalTests.toString().padEnd(42)}║`);
console.log(`║  ✅ Passed:    ${report.summary.passed.toString().padEnd(42)}║`);
console.log(`║  ❌ Failed:    ${report.summary.failed.toString().padEnd(42)}║`);
console.log(`║  Pass Rate:    ${report.summary.passRate.padEnd(42)}║`);
console.log('╠════════════════════════════════════════════════════════════╣');
console.log('║  Por Prioridad:                                            ║');
console.log(`║    CRITICAL: ${report.byPriority.CRITICAL.passed}/${report.byPriority.CRITICAL.total}`.padEnd(61) + '║');
console.log(`║    HIGH:     ${report.byPriority.HIGH.passed}/${report.byPriority.HIGH.total}`.padEnd(61) + '║');
console.log(`║    MEDIUM:   ${report.byPriority.MEDIUM.passed}/${report.byPriority.MEDIUM.total}`.padEnd(61) + '║');
console.log('╚════════════════════════════════════════════════════════════╝');

if (failed.length > 0) {
  console.log('\n❌ Tests Fallidos:');
  failed.forEach(f => {
    console.log(`   - ${f.testId}: ${f.testName}`);
  });
}

return [{ json: report }];
